import { _electron, expect, test } from '@playwright/test'
import { cpus, release, totalmem, tmpdir } from 'node:os'
import { mkdtemp, readFile, rm } from 'node:fs/promises'
import { join } from 'node:path'
import { performance } from 'node:perf_hooks'
import { electronExecutable } from '../../tools/dev/electron-executable'
import { buildDirectory } from '../../tools/lib/paths'
import { hostTarget } from '../../tools/lib/targets'
import { budgets } from './budgets'
import { execFile } from 'node:child_process'
import { promisify } from 'node:util'

test('measures twenty fresh processes and confirms all observed child processes exit', async ({}, info) => {
  const runtime = buildDirectory(hostTarget())
  const profile = await mkdtemp(join(tmpdir(), 'kisaki-performance-'))
  const samples: { milliseconds: number; workingSetKiB: number }[] = []
  try {
    for (let index = 0; index < budgets.samples; index++) {
      const env: Record<string, string> = Object.fromEntries(
        Object.entries(process.env).filter(
          (entry): entry is [string, string] => entry[1] !== undefined,
        ),
      )
      delete env.ELECTRON_RUN_AS_NODE

      const sample = `Sample ${index + 1}`
      const { application, start } = await test.step(`${sample}: launch`, async () => {
        const start = performance.now()
        const application = await _electron.launch({
          executablePath: electronExecutable(),
          args: [join(runtime, 'main/entry.js'), `--profile=${profile}`],
          env,
        })
        return { application, start }
      })

      let pids: number[] = []
      try {
        const milliseconds = await test.step(`${sample}: window ready`, async () => {
          const window = await application.firstWindow()
          await window.getByRole('button', { name: 'Close window' }).waitFor()
          return performance.now() - start
        })
        const metrics = await test.step(`${sample}: process metrics`, () =>
          application.evaluate(({ app, BrowserWindow }) => {
            const report = (event: string, details?: unknown) =>
              console.info(
                'SHUTDOWN_OBSERVATION',
                JSON.stringify({ at: Date.now(), event, details }),
              )
            app.on('before-quit', (event) =>
              report('before-quit', { prevented: event.defaultPrevented }),
            )
            app.on('will-quit', (event) =>
              report('will-quit', { prevented: event.defaultPrevented }),
            )
            app.on('quit', (_event, code) => report('quit', { code }))
            app.on('window-all-closed', () => report('window-all-closed'))
            for (const window of BrowserWindow.getAllWindows()) {
              const id = window.id
              window.on('close', (event) =>
                report('window-close', { id, prevented: event.defaultPrevented }),
              )
              window.on('closed', () => report('window-closed', { id }))
              window.webContents.on('destroyed', () => report('web-contents-destroyed', { id }))
              window.webContents.on('will-prevent-unload', (event) =>
                report('will-prevent-unload', { id, prevented: event.defaultPrevented }),
              )
              window.webContents.on('render-process-gone', (_event, details) =>
                report('render-process-gone', { id, ...details }),
              )
            }
            report('observers-installed', { pid: process.pid })

            return app
              .getAppMetrics()
              .map(({ pid, memory }) => ({ pid, workingSetSize: memory.workingSetSize }))
          }))
        pids = metrics.map((metric) => metric.pid)
        samples.push({
          milliseconds,
          workingSetKiB: metrics.reduce((sum, metric) => sum + metric.workingSetSize, 0),
        })
      } finally {
        const pid = application.process().pid!
        const inspect = setTimeout(() => {
          console.info(
            'SHUTDOWN_STILL_PENDING',
            JSON.stringify({ sample, pid, observedPids: pids }),
          )
          void Promise.all(
            pids.map(async (observedPid) => {
              try {
                await promisify(execFile)('/usr/bin/sample', [
                  String(observedPid),
                  '1',
                  '1',
                  '-file',
                  info.outputPath('sample-' + (index + 1) + '-pid-' + observedPid + '.txt'),
                ])
              } catch (error) {
                console.error('PROCESS_SAMPLE_FAILED', observedPid, String(error))
              }
            }),
          )
        }, 10_000)
        inspect.unref()
        try {
          await test.step(sample + ': close', async () => {
            await application.close()
          })
        } finally {
          clearTimeout(inspect)
        }
      }

      await test.step(`${sample}: observed processes exit`, () =>
        expect
          .poll(
            () =>
              pids.filter((pid) => {
                try {
                  process.kill(pid, 0)
                  return true
                } catch {
                  return false
                }
              }),
            { timeout: 5_000 },
          )
          .toEqual([]))
    }

    const sorted = samples.map((sample) => sample.milliseconds).sort((a, b) => a - b)
    const p95 = sorted[Math.ceil(sorted.length * 0.95) - 1]!
    const mean = sorted.reduce((sum, value) => sum + value, 0) / sorted.length
    const middle = Math.floor(sorted.length / 2)
    const median =
      sorted.length % 2 === 0 ? (sorted[middle - 1]! + sorted[middle]!) / 2 : sorted[middle]!

    const report = {
      target: hostTarget(),
      osRelease: release(),
      cpu: cpus()[0]?.model,
      memoryBytes: totalmem(),
      mode: 'fresh processes, warm OS disk cache, isolated retained profile, W00 shell only',
      build: JSON.parse(await readFile(join(runtime, 'build.json'), 'utf8')),
      samples,
      medianMs: median,
      p95Ms: p95,
      maxMs: sorted.at(-1),
      standardDeviationMs: Math.sqrt(
        sorted.reduce((sum, value) => sum + (value - mean) ** 2, 0) / sorted.length,
      ),
    }
    await info.attach('startup.json', {
      body: JSON.stringify(report, null, 2),
      contentType: 'application/json',
    })
    expect(p95).toBeLessThanOrEqual(budgets.engineeringShellStartupP95Ms)
  } finally {
    await rm(profile, { recursive: true, force: true })
  }
})

import { createServer } from 'vite'
import { isAbsolute, join, relative, sep } from 'node:path'
import { appRoot, repositoryRoot } from '../lib/paths'
import { publicPackageBuildInputs } from '../lib/package-inputs'
import type { DependencySnapshot } from './dependencies'
import type { DesktopDependency } from './dependencies'
import type { DependencyResolver } from './dependencies'

/** Vite and the public-package snapshot serving this development session. */
export interface DevelopmentRenderer {
  readonly url: string
  /** Resolve candidate exports through Vite's current client environment, including after restart. */
  resolveDependency: DependencyResolver
  /** Change public imports after a successful package build and refresh loaded documents. */
  adopt(snapshot: DependencySnapshot): Promise<void>
  /** Observe runtime and package inputs; returns the watcher subscription cleanup. */
  watch(listener: (change: 'runtime' | 'public-package') => void): () => void
  close(): Promise<void>
}

function contains(parent: string, path: string): boolean {
  const child = relative(parent, path)
  return child !== '..' && !child.startsWith(`..${sep}`) && !isAbsolute(child)
}

/** Start the renderer server and retain its current public-package resolution until close(). */
export async function startRenderer(
  members: DesktopDependency[],
  snapshotDirectory: string,
): Promise<DevelopmentRenderer> {
  let snapshot: DependencySnapshot | undefined
  const listeners = new Set<(change: 'runtime' | 'public-package') => void>()
  const packageInputs = (
    await Promise.all(members.map((member) => publicPackageBuildInputs(member.path)))
  ).flat()
  const runtimeInputs = [
    ...['main', 'preload', 'extension-host', 'shared'].map((name) =>
      join(appRoot, 'src', name),
    ),
    join(appRoot, 'native'),
    join(appRoot, 'assets'),
    ...['main', 'preload', 'extension-host', 'renderer'].map((name) =>
      join(appRoot, 'config', 'vite', `vite.config.${name}.ts`),
    ),
    join(appRoot, 'package.json'),
    join(repositoryRoot, 'pnpm-lock.yaml'),
  ]

  /** Forward owned source changes from each watcher created when Vite starts or restarts. */
  function changed(_event: string, path: string): void {
    let change: 'runtime' | 'public-package'
    if (packageInputs.some((input) => contains(input, path))) {
      change = 'public-package'
    } else if (runtimeInputs.some((input) => contains(input, path))) {
      change = 'runtime'
    } else {
      return
    }
    for (const listener of listeners) listener(change)
  }

  const server = await createServer({
    configFile: join(appRoot, 'config', 'vite', 'vite.config.renderer.ts'),
    mode: 'development',
    optimizeDeps: { exclude: members.map((member) => member.name) },
    plugins: [
      {
        name: 'desktop-public-dependency-snapshots',
        enforce: 'pre',
        configureServer(vite) {
          vite.watcher.add([...packageInputs, ...runtimeInputs])
          vite.watcher.on('all', changed)
        },
        async resolveId(source, importer, options) {
          // Imports inside a snapshot keep that generation's package resolution.
          if (importer && contains(snapshotDirectory, importer)) return null
          const specifier = source.replace(/[?#].*$/, '')
          const member = members.find(
            ({ name }) => specifier === name || specifier.startsWith(`${name}/`),
          )
          if (!member) return null

          const packageRoot = snapshot?.packages.get(member.name)
          if (!packageRoot) throw new Error('Public dependencies are not ready')
          return this.resolve(source, join(packageRoot, 'package.json'), {
            ...options,
            skipSelf: true,
          })
        },
      },
    ],
  })

  try {
    await server.listen()
    const initialUrl = server.resolvedUrls?.local[0]
    if (!initialUrl) throw new Error('Renderer server did not publish a listening address')
    let url = initialUrl

    return {
      get url() {
        return url
      },

      resolveDependency: (...args) =>
        server.environments.client.pluginContainer.resolveId(...args),

      async adopt(nextSnapshot) {
        if (snapshot?.id === nextSnapshot.id) return

        const initialBuild = snapshot === undefined
        snapshot = nextSnapshot
        if (initialBuild) {
          // Dependencies were unavailable at startup; discard unresolved optimizer entries.
          await server.restart()
          const address = server.resolvedUrls?.local[0]
          if (!address) throw new Error('Renderer restart did not publish a listening address')
          url = address
        } else {
          server.moduleGraph.invalidateAll()
          server.ws.send({ type: 'full-reload' })
        }
      },

      watch(listener) {
        listeners.add(listener)
        return () => {
          listeners.delete(listener)
        }
      },

      close() {
        listeners.clear()
        return server.close()
      },
    }
  } catch (cause) {
    await server.close()
    throw cause
  }
}
